package org.brightstats.stats;

import java.util.*;
import org.apache.commons.math3.distribution.*;

/** Pool matched parameter estimates and covariance, never imputed values or P values. */
public final class RubinPooling {
    private RubinPooling(){}
    public record Estimate(List<String> labels,double[] estimates,double[][] covariance){public Estimate{labels=List.copyOf(labels);estimates=estimates.clone();covariance=Matrices.copy(covariance);if(labels.isEmpty()||labels.size()!=estimates.length||new HashSet<>(labels).size()!=labels.size()||covariance.length!=estimates.length)throw new IllegalArgumentException("Pool matching named parameter vectors and square covariances.");for(var row:covariance)if(row==null||row.length!=estimates.length)throw new IllegalArgumentException("Covariance rows must be square.");for(int i=0;i<estimates.length;i++){if(covariance[i][i]<0)throw new IllegalArgumentException("A complete-data variance is negative.");if(covariance[i].length!=estimates.length||!Double.isFinite(estimates[i]))throw new IllegalArgumentException("Invalid pooling dimensions or estimate.");for(int j=0;j<estimates.length;j++)if(!Double.isFinite(covariance[i][j])||Math.abs(covariance[i][j]-covariance[j][i])>1e-8*Math.max(1,Math.abs(covariance[i][j])))throw new IllegalArgumentException("Pooling needs finite symmetric covariance from every analysis.");}if(Matrices.minEigenvalue(covariance)<-1e-10)throw new IllegalArgumentException("A complete-data covariance is not positive semidefinite.");}@Override public double[] estimates(){return estimates.clone();}@Override public double[][] covariance(){return Matrices.copy(covariance);}}
    public record Term(String parameter,double estimate,double standardError,double degreesOfFreedom,double relativeIncreaseVariance,double fractionMissingInformation,double statistic,double pValue,double lower,double upper){}
    public record Result(int imputations,double confidence,Double completeDegreesOfFreedom,List<String> labels,double[] estimates,double[][] withinCovariance,double[][] betweenCovariance,double[][] totalCovariance,List<Term> terms,List<String> warnings){public Result{labels=List.copyOf(labels);estimates=estimates.clone();withinCovariance=Matrices.copy(withinCovariance);betweenCovariance=Matrices.copy(betweenCovariance);totalCovariance=Matrices.copy(totalCovariance);terms=List.copyOf(terms);warnings=List.copyOf(warnings);}}
    public static Result pool(List<Estimate> fits,double confidence,Double completeDf,boolean[] testable){Inference.confidence(confidence);if(fits==null||fits.size()<2||completeDf!=null&&(!(completeDf>0)||!Double.isFinite(completeDf)))throw new IllegalArgumentException("Pool at least two complete analyses; any supplied complete-data degrees of freedom must be positive and finite.");int m=fits.size(),q=fits.getFirst().labels().size();if(testable.length!=q)throw new IllegalArgumentException("Declare the ratio-test eligibility of each parameter.");List<String> labels=fits.getFirst().labels();double[] mean=new double[q];double[][] within=new double[q][q],between=new double[q][q],total=new double[q][q];for(var fit:fits){if(!fit.labels().equals(labels))throw new IllegalArgumentException("Imputation parameter identities/order differ.");for(int i=0;i<q;i++){mean[i]+=fit.estimates[i]/m;for(int j=0;j<q;j++)within[i][j]+=fit.covariance[i][j]/m;}}for(var fit:fits)for(int i=0;i<q;i++)for(int j=0;j<q;j++)between[i][j]+=(fit.estimates[i]-mean[i])*(fit.estimates[j]-mean[j])/(m-1);for(int i=0;i<q;i++)for(int j=0;j<q;j++)total[i][j]=within[i][j]+(1+1.0/m)*between[i][j];
        if(!Arrays.stream(mean).allMatch(Double::isFinite)||!Arrays.stream(total).flatMapToDouble(Arrays::stream).allMatch(Double::isFinite))throw new IllegalArgumentException("Pooled estimates/covariance overflowed; rescale the analysis rather than interpreting nonfinite uncertainty.");List<Term> terms=new ArrayList<>();for(int i=0;i<q;i++){double additional=(1+1.0/m)*between[i][i],r=within[i][i]>0?additional/within[i][i]:additional==0?0:Double.POSITIVE_INFINITY,lambda=total[i][i]>0?additional/total[i][i]:0,old=additional==0?Double.POSITIVE_INFINITY:(m-1)*Math.pow(1+1/r,2),df=old;if(completeDf!=null){double observed=((completeDf+1)/(completeDf+3))*completeDf*(1-lambda);df=observed>0?1/(1/old+1/observed):Double.NaN;}double se=Math.sqrt(total[i][i]),stat=testable[i]?Inference.ratio(mean[i],se):Double.NaN,p=Double.NaN,critical=Double.NaN;if(Double.isFinite(df)&&df>0){TDistribution t=new TDistribution(df);critical=t.inverseCumulativeProbability((1+confidence)/2);p=Double.isNaN(stat)?Double.NaN:2*t.cumulativeProbability(-Math.abs(stat));}else if(df==Double.POSITIVE_INFINITY){critical=new NormalDistribution().inverseCumulativeProbability((1+confidence)/2);p=Inference.normalTwoSided(stat);}double fmi=Double.isInfinite(r)?1:(r+2/(df+3))/(r+1);terms.add(new Term(labels.get(i),mean[i],se,df,r,fmi,stat,p,mean[i]-critical*se,mean[i]+critical*se));}
        List<String> warnings=new ArrayList<>();warnings.add("Rubin pooling combines matched estimates and within/between-imputation covariance; it does not pool raw datasets, likelihoods or P values.");warnings.add(completeDf==null?"Large complete-sample inference assumed; Rubin finite-imputation degrees of freedom are used. Supply scientifically appropriate finite complete-data df to request the Barnard-Rubin adjustment.":"Barnard-Rubin finite complete-data degrees-of-freedom adjustment applied.");warnings.add("Generic ratio tests are suppressed for declared variance/covariance parameters; pooling is conditional on congenial imputation and valid complete-data analyses.");return new Result(m,confidence,completeDf,labels,mean,within,between,total,terms,warnings);
    }
}
